import { PrismaClient } from "../generated/prisma/client.js";
import { PrismaPg } from "@prisma/adapter-pg";

const adapter = new PrismaPg({ connectionString: process.env.DATABASE_URL });
const prisma = new PrismaClient({ adapter });

async function main() {
  // Data generation (authors, publishers, genres, books, users, reviews,
  // orders) lands in the next pass — this just proves the seed entry point
  // and Prisma connection work end to end.
  console.log("Seed entry point ready; no data generated yet.");
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

