// This is your Prisma schema file,
// learn more about it in the docs: https://pris.ly/d/prisma-schema

generator client {
  provider = "prisma-client"
  output   = "../generated/prisma"
}

datasource db {
  provider = "postgresql"
}

enum Format {
  HARDCOVER
  SOFTCOVER
  AUDIOBOOK
  EREADER
}

model Author {
  id    String @id @default(cuid())
  name  String
  books Book[] @relation("BookAuthors")

  @@index([name])
}

model Publisher {
  id    String @id @default(cuid())
  name  String
  books Book[]
}

model Genre {
  id    String @id @default(cuid())
  name  String
  books Book[] @relation("BookGenres")
}

model Book {
  id          String      @id @default(cuid())
  title       String
  price       Decimal     @db.Decimal(10, 2)
  formats     Format[]
  publisher   Publisher   @relation(fields: [publisherId], references: [id])
  publisherId String
  authors     Author[]    @relation("BookAuthors")
  genres      Genre[]     @relation("BookGenres")
  reviews     Review[]
  orderItems  OrderItem[]
  createdAt   DateTime    @default(now())

  @@index([title])
}

model User {
  id      String   @id @default(cuid())
  name    String
  reviews Review[]
  orders  Order[]

  @@index([name])
}

// One review per user per book; immutable (no update/delete flow), enforced
// by the unique constraint below.
model Review {
  id        String   @id @default(cuid())
  book      Book     @relation(fields: [bookId], references: [id])
  bookId    String
  user      User     @relation(fields: [userId], references: [id])
  userId    String
  rating    Int
  createdAt DateTime @default(now())

  @@unique([bookId, userId])
  @@index([bookId])
}

model Order {
  id        String      @id @default(cuid())
  user      User        @relation(fields: [userId], references: [id])
  userId    String
  items     OrderItem[]
  createdAt DateTime    @default(now())
}

// unitPrice snapshots Book.price at the moment of checkout, independent of
// later price changes.
model OrderItem {
  id        String  @id @default(cuid())
  order     Order   @relation(fields: [orderId], references: [id])
  orderId   String
  book      Book    @relation(fields: [bookId], references: [id])
  bookId    String
  format    Format
  quantity  Int
  unitPrice Decimal @db.Decimal(10, 2)
}

