/*
* This file exports all enum related types from the schema.
*
* 🟢 You can import this file directly.
*/

export const Format = {
  HARDCOVER: 'HARDCOVER',
  SOFTCOVER: 'SOFTCOVER',
  AUDIOBOOK: 'AUDIOBOOK',
  EREADER: 'EREADER'
} as const

export type Format = (typeof Format)[keyof typeof Format]

// This is your Prisma schema file,
// learn more about it in the docs: https://pris.ly/d/prisma-schema

generator client {
  provider = "prisma-client"
  output   = "../generated/prisma"
}

datasource db {
  provider = "postgresql"
}

enum Format {
  HARDCOVER
  SOFTCOVER
  AUDIOBOOK
  EREADER
}

model Author {
  id    String       @id @default(cuid())
  name  String
  books BookAuthor[]

  @@index([name])
}

model Publisher {
  id    String @id @default(cuid())
  name  String
  books Book[]
}

model Genre {
  id    String      @id @default(cuid())
  name  String
  books BookGenre[]
}

model Book {
  id          String       @id @default(cuid())
  title       String
  price       Decimal      @db.Decimal(10, 2)
  formats     Format[]
  publisher   Publisher    @relation(fields: [publisherId], references: [id])
  publisherId String
  authors     BookAuthor[]
  genres      BookGenre[]
  reviews     Review[]
  orderItems  OrderItem[]
  createdAt   DateTime     @default(now())

  @@index([title])
}

// Explicit join model (not an implicit m2m) so seed data at assignment scale
// (~10k books × 1-3 authors each) can be bulk-inserted via createMany instead
// of one connect() round-trip per pair.
model BookAuthor {
  book     Book   @relation(fields: [bookId], references: [id])
  bookId   String
  author   Author @relation(fields: [authorId], references: [id])
  authorId String

  @@id([bookId, authorId])
}

model BookGenre {
  book    Book   @relation(fields: [bookId], references: [id])
  bookId  String
  genre   Genre  @relation(fields: [genreId], references: [id])
  genreId String

  @@id([bookId, genreId])
}

model User {
  id      String   @id @default(cuid())
  name    String
  reviews Review[]
  orders  Order[]

  @@index([name])
}

// One review per user per book; immutable (no update/delete flow), enforced
// by the unique constraint below.
model Review {
  id        String   @id @default(cuid())
  book      Book     @relation(fields: [bookId], references: [id])
  bookId    String
  user      User     @relation(fields: [userId], references: [id])
  userId    String
  rating    Int
  createdAt DateTime @default(now())

  @@unique([bookId, userId])
  @@index([bookId])
}

model Order {
  id        String      @id @default(cuid())
  user      User        @relation(fields: [userId], references: [id])
  userId    String
  items     OrderItem[]
  createdAt DateTime    @default(now())
}

// unitPrice snapshots Book.price at the moment of checkout, independent of
// later price changes.
model OrderItem {
  id        String  @id @default(cuid())
  order     Order   @relation(fields: [orderId], references: [id])
  orderId   String
  book      Book    @relation(fields: [bookId], references: [id])
  bookId    String
  format    Format
  quantity  Int
  unitPrice Decimal @db.Decimal(10, 2)
}

