import json
import sys
from pathlib import Path

src = Path.home() / "Documents" / "bookie-session-transcript-2026-07-18.jsonl"
out = Path.home() / "Documents" / "bookie-CHATLOG.md"

def summarize_tool_input(name, inp):
    if not isinstance(inp, dict):
        return ""
    for key in ("file_path", "command", "query", "prompt", "url"):
        if key in inp and isinstance(inp[key], str):
            val = inp[key].replace("\n", " ")
            if len(val) > 140:
                val = val[:140] + "…"
            return f" — `{val}`"
    return ""

lines = []
lines.append("# Bookie Assignment — Chat Log\n")
lines.append("_Rendered from the raw session transcript for readability. Tool calls are summarized (name + key argument); full tool output/results are omitted here — see the raw `.jsonl` backup if you need exact tool payloads._\n")

with src.open() as f:
    for raw in f:
        raw = raw.strip()
        if not raw:
            continue
        try:
            entry = json.loads(raw)
        except json.JSONDecodeError:
            continue

        etype = entry.get("type")

        if etype == "user":
            msg = entry.get("message", {})
            content = msg.get("content")
            if isinstance(content, str):
                text = content.strip()
                # Skip pure local-command-stdout / caveat noise blocks with nothing else
                if text.startswith("<local-command-stdout>") and text.endswith("</local-command-stdout>"):
                    continue
                if not text:
                    continue
                lines.append(f"### 🧑 User\n\n{text}\n")
            elif isinstance(content, list):
                for block in content:
                    if block.get("type") == "text" and block.get("text", "").strip():
                        lines.append(f"### 🧑 User\n\n{block['text'].strip()}\n")
                    elif block.get("type") == "tool_result":
                        pass  # omit raw tool results, too large / not conversational

        elif etype == "assistant":
            msg = entry.get("message", {})
            content = msg.get("content", [])
            text_parts = []
            tool_calls = []
            for block in content:
                btype = block.get("type")
                if btype == "text" and block.get("text", "").strip():
                    text_parts.append(block["text"].strip())
                elif btype == "tool_use":
                    tool_calls.append(f"- `{block.get('name')}`{summarize_tool_input(block.get('name'), block.get('input', {}))}")
            if text_parts:
                lines.append(f"### 🤖 Assistant\n\n{'\\n\\n'.join(text_parts)}\n")
            if tool_calls:
                lines.append("**Tool calls:**\n" + "\n".join(tool_calls) + "\n")

out.write_text("\n".join(lines), encoding="utf-8")
print(f"Wrote {out} ({out.stat().st_size} bytes)")

import "dotenv/config";
