import { gql } from "@apollo/client";
import { useQuery } from "@apollo/client/react";
import type {
  BooksQueryArgs,
  BooksQueryData,
  GenresQueryData,
  OrdersQueryArgs,
  OrdersQueryData,
  ReportQueryData,
  UsersQueryArgs,
  UsersQueryData,
} from "@bookie/shared";
import { BOOK_FIELDS } from "@/graphql/fragments";

export const BOOKS_QUERY = gql`
  ${BOOK_FIELDS}
  query Books($search: String, $genreId: ID, $page: Int, $pageSize: Int) {
    books(search: $search, genreId: $genreId, page: $page, pageSize: $pageSize) {
      items {
        ...BookFields
      }
      totalCount
      page
      pageSize
      totalPages
    }
  }
`;

export function useBooksQuery(variables: BooksQueryArgs) {
  return useQuery<BooksQueryData, BooksQueryArgs>(BOOKS_QUERY, { variables });
}

export const GENRES_QUERY = gql`
  query Genres {
    genres {
      id
      name
    }
  }
`;

export function useGenresQuery() {
  return useQuery<GenresQueryData>(GENRES_QUERY);
}

export const USERS_QUERY = gql`
  query Users($search: String, $limit: Int) {
    users(search: $search, limit: $limit) {
      id
      name
    }
  }
`;

export function useUsersQuery(variables: UsersQueryArgs) {
  return useQuery<UsersQueryData, UsersQueryArgs>(USERS_QUERY, { variables });
}

export const ORDERS_QUERY = gql`
  ${BOOK_FIELDS}
  query Orders($userId: ID!) {
    orders(userId: $userId) {
      id
      createdAt
      total
      items {
        id
        format
        quantity
        unitPrice
        book {
          ...BookFields
        }
      }
    }
  }
`;

export function useOrdersQuery(variables: OrdersQueryArgs) {
  return useQuery<OrdersQueryData, OrdersQueryArgs>(ORDERS_QUERY, { variables });
}

export const REPORT_QUERY = gql`
  query Report {
    report {
      totalBooksPurchased
      byGenre {
        totalBooksPurchased
        genre {
          id
          name
        }
      }
    }
  }
`;

export function useReportQuery() {
  return useQuery<ReportQueryData>(REPORT_QUERY);
}

