import { print } from "graphql";
import {
  BOOKS_QUERY,
  GENRES_QUERY,
  USERS_QUERY,
  ORDERS_QUERY,
  REPORT_QUERY,
} from "/home/tricky/PycharmProjects/bookie/frontend/src/graphql/queries.ts";
import {
  SUBMIT_REVIEW_MUTATION,
  CHECKOUT_MUTATION,
} from "/home/tricky/PycharmProjects/bookie/frontend/src/graphql/mutations.ts";

const GRAPHQL_URL = "http://localhost:4000/";

async function exec(name: string, doc: unknown, variables: Record<string, unknown>) {
  const query = print(doc as never);
  const res = await fetch(GRAPHQL_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ query, variables }),
  });
  const json = await res.json();
  const ok = !json.errors;
  console.log(`[${ok ? "OK" : "FAIL"}] ${name}`, ok ? "" : JSON.stringify(json.errors));
  return json.data;
}

async function main() {
  const booksData = await exec("Books", BOOKS_QUERY, { search: "the", page: 1, pageSize: 2 });
  await exec("Genres", GENRES_QUERY, {});
  const usersData = await exec("Users", USERS_QUERY, { limit: 3 });
  const userId = usersData.users[0].id;
  await exec("Orders", ORDERS_QUERY, { userId });
  await exec("Report", REPORT_QUERY, {});

  const bookId = booksData.books.items[1].id;
  const reviewResult = await exec("SubmitReview", SUBMIT_REVIEW_MUTATION, {
    bookId,
    userId,
    rating: 5,
  });
  console.log("  review ->", reviewResult?.submitReview?.book?.title, reviewResult?.submitReview?.rating);

  const checkoutResult = await exec("Checkout", CHECKOUT_MUTATION, {
    userId,
    items: [{ bookId, format: "EREADER", quantity: 1 }],
  });
  console.log("  checkout ->", checkoutResult?.checkout?.total, checkoutResult?.checkout?.items?.length);
}

main();

