import { describe, expect, it } from "vitest";
import { render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { ApolloClient, HttpLink, InMemoryCache } from "@apollo/client";
import { ApolloProvider } from "@apollo/client/react";
import { MemoryRouter } from "react-router";
import App from "../App";
import { CurrentUserProvider } from "@/context/UserContext";
import { CartProvider } from "@/context/CartContext";

// Not part of the regular suite: this drives the real app against the real
// running backend/DB (see package.json — only picked up by the dedicated
// `test:integration` script) as a stand-in for manual browser testing in an
// environment with no browser available.
