import { describe, expect, it } from "vitest";
import { render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { ApolloClient, HttpLink, InMemoryCache } from "@apollo/client";
import { ApolloProvider } from "@apollo/client/react";
import { MemoryRouter } from "react-router";
import App from "../App";
import { CurrentUserProvider } from "@/context/UserContext";
import { CartProvider } from "@/context/CartContext";

// Scratch verification only (not part of the permanent suite — deleted after
// this run): drives the real app against the real running backend/DB as a
// stand-in for manual browser testing in an environment with no browser
// available.
const client = new ApolloClient({
  link: new HttpLink({ uri: "http://localhost:4000/" }),
  cache: new InMemoryCache(),
});

function renderApp() {
  return render(
    <ApolloProvider client={client}>
      <CurrentUserProvider>
        <CartProvider>
          <MemoryRouter>
            <App />
          </MemoryRouter>
        </CartProvider>
      </CurrentUserProvider>
    </ApolloProvider>,
  );
}

describe("manual smoke test against the live backend", () => {
  it("browses, selects a user, adds to cart, reviews, and checks out", async () => {
    const user = userEvent.setup();
    renderApp();

    // Browse: books load from the real DB.
    await waitFor(() => expect(screen.getByText(/books$/)).toBeInTheDocument(), { timeout: 5000 });
    const bookCountText = screen.getByText(/books$/).textContent;
    expect(Number(bookCountText?.split(" ")[0])).toBeGreaterThan(9000);

    // Select a user via the searchable combobox.
    await user.click(screen.getByRole("combobox", { name: "Select a user" }));
    const searchInput = await screen.findByPlaceholderText("Search users…");
    await user.type(searchInput, "Ava");
    const userOptions = await screen.findAllByText(/Ava/);
    await user.click(userOptions[0]!);
    await waitFor(() => expect(screen.queryByText("Select a user…")).not.toBeInTheDocument());

    // Add the first visible book to the cart.
    const addButtons = await screen.findAllByRole("button", { name: /^Add$/ });
    await user.click(addButtons[0]!);
    await waitFor(() => expect(screen.getByText("Added")).toBeInTheDocument());

    // Open the cart drawer and confirm the item is there.
    await user.click(screen.getByRole("button", { name: /Cart/ }));
    const dialog = await screen.findByRole("dialog");
    expect(within(dialog).getByText(/Checkout/)).toBeInTheDocument();
    expect(within(dialog).queryByText("Your cart is empty.")).not.toBeInTheDocument();

    // Checkout.
    await user.click(within(dialog).getByRole("button", { name: /Checkout/ }));
    await waitFor(() => expect(within(dialog).getByText(/Order placed/)).toBeInTheDocument(), {
      timeout: 5000,
    });
  }, 15000);
});

