    expect(loadMore).toBeInTheDocument();

    await user.click(loadMore);
    // after loading, more items should be present and the control should
    // still be there (or gone, if we've exhausted ~1000 users) — either way
    // it must not throw and must not stay permanently stuck on "Loading…"
    await screen.findByText(/Load more|No users found/, {}, { timeout: 3000 });

    const list = screen.getByRole("listbox");
    const items = within(list).getAllByRole("option");
    expect(items.length).toBeGreaterThan(20);
