1	import { GraphQLError } from "graphql";
2	import type {
3	  BooksQueryArgs,
4	  CheckoutArgs,
5	  OrdersQueryArgs,
6	  SubmitReviewArgs,
7	  UsersQueryArgs,
8	} from "@bookie/shared";
9	import { Prisma } from "../generated/prisma/client.js";
10	import type { GraphQLContext } from "./context.js";
11	
12	const bookInclude = {
13	  publisher: true,
14	  authors: { include: { author: true } },
15	  genres: { include: { genre: true } },
16	} satisfies Prisma.BookInclude;
17	
18	type BookWithRelations = Prisma.BookGetPayload<{ include: typeof bookInclude }>;
19	
20	interface RatingSummary {
21	  average: number | null;
22	  count: number;
23	}
24	
25	// Single groupBy over Review for however many book ids are in play (a page
26	// of books, or the handful of books in a user's orders) instead of one query
27	// per book — keeps book listings and order histories at O(1) review queries.
28	async function loadRatings(
29	  prisma: GraphQLContext["prisma"],
30	  bookIds: string[],
31	): Promise<Map<string, RatingSummary>> {
32	  if (bookIds.length === 0) return new Map();
33	  const grouped = await prisma.review.groupBy({
34	    by: ["bookId"],
35	    where: { bookId: { in: bookIds } },
36	    _avg: { rating: true },
37	    _count: { rating: true },
38	  });
39	  return new Map(
40	    grouped.map((row) => [row.bookId, { average: row._avg.rating, count: row._count.rating }]),
41	  );
42	}
43	
44	// Same batching idea as loadRatings, but scoped to a single user's own
45	// reviews so the UI can pre-fill "your rating" without an extra round trip
46	// per book.
47	async function loadMyRatings(
48	  prisma: GraphQLContext["prisma"],
49	  userId: string | undefined,
50	  bookIds: string[],
51	): Promise<Map<string, number>> {
52	  if (!userId || bookIds.length === 0) return new Map();
53	  const reviews = await prisma.review.findMany({
54	    where: { userId, bookId: { in: bookIds } },
55	    select: { bookId: true, rating: true },
56	  });
57	  return new Map(reviews.map((review) => [review.bookId, review.rating]));
58	}
59	
60	function toBookDTO(
61	  book: BookWithRelations,
62	  ratings: Map<string, RatingSummary>,
63	  myRatings: Map<string, number> = new Map(),
64	) {
65	  const rating = ratings.get(book.id);
66	  return {
67	    id: book.id,
68	    title: book.title,
69	    price: Number(book.price),
70	    formats: book.formats,
71	    publisher: book.publisher,
72	    authors: book.authors.map((bookAuthor) => bookAuthor.author),
73	    genres: book.genres.map((bookGenre) => bookGenre.genre),
74	    averageRating: rating?.average ?? null,
75	    reviewCount: rating?.count ?? 0,
76	    myRating: myRatings.get(book.id) ?? null,
77	  };
78	}
79	
80	// Order totals are summed in JS floating point, which can leave artifacts
81	// like 35.400000000000006 — round to the nearest cent before returning.
82	function roundCents(amount: number): number {
83	  return Math.round(amount * 100) / 100;
84	}
85	
86	function orderTotal(items: { unitPrice: number; quantity: number }[]): number {
87	  return roundCents(items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0));
88	}
89	
90	function assertValidRating(rating: number): void {
91	  if (!Number.isInteger(rating) || rating < 1 || rating > 5) {
92	    throw new GraphQLError("rating must be an integer between 1 and 5", {
93	      extensions: { code: "BAD_USER_INPUT" },
94	    });
95	  }
96	}
97	
98	export const resolvers = {
99	  Query: {
100	    books: async (_parent: unknown, args: BooksQueryArgs, ctx: GraphQLContext) => {
101	      const page = args.page ?? 1;
102	      const pageSize = args.pageSize ?? 20;
103	
104	      const where: Prisma.BookWhereInput = {};
105	      if (args.search) {
106	        where.OR = [
107	          { title: { contains: args.search, mode: "insensitive" } },
108	          { authors: { some: { author: { name: { contains: args.search, mode: "insensitive" } } } } },
109	        ];
110	      }
111	      if (args.genreId) {
112	        where.genres = { some: { genreId: args.genreId } };
113	      }
114	
115	      const [totalCount, books] = await Promise.all([
116	        ctx.prisma.book.count({ where }),
117	        ctx.prisma.book.findMany({
118	          where,
119	          skip: (page - 1) * pageSize,
120	          take: pageSize,
121	          orderBy: { title: "asc" },
122	          include: bookInclude,
123	        }),
124	      ]);
125	
126	      const bookIds = books.map((book) => book.id);
127	      const [ratings, myRatings] = await Promise.all([
128	        loadRatings(ctx.prisma, bookIds),
129	        loadMyRatings(ctx.prisma, args.userId, bookIds),
130	      ]);
131	
132	      return {
133	        items: books.map((book) => toBookDTO(book, ratings, myRatings)),
134	        totalCount,
135	        page,
136	        pageSize,
137	        totalPages: pageSize > 0 ? Math.ceil(totalCount / pageSize) : 0,
138	      };
139	    },
140	
141	    genres: (_parent: unknown, _args: unknown, ctx: GraphQLContext) =>
142	      ctx.prisma.genre.findMany({ orderBy: { name: "asc" } }),
143	
144	    users: (_parent: unknown, args: UsersQueryArgs, ctx: GraphQLContext) =>
145	      ctx.prisma.user.findMany({
146	        where: args.search ? { name: { contains: args.search, mode: "insensitive" } } : {},
147	        orderBy: { name: "asc" },
148	        skip: args.offset ?? 0,
149	        take: args.limit ?? 20,
150	      }),
151	
152	    orders: async (_parent: unknown, args: OrdersQueryArgs, ctx: GraphQLContext) => {
153	      const orders = await ctx.prisma.order.findMany({
154	        where: { userId: args.userId },
155	        orderBy: { createdAt: "desc" },
156	        include: { items: { include: { book: { include: bookInclude } } } },
157	      });
158	
159	      const bookIds = [...new Set(orders.flatMap((order) => order.items.map((item) => item.bookId)))];
160	      const [ratings, myRatings] = await Promise.all([
161	        loadRatings(ctx.prisma, bookIds),
162	        loadMyRatings(ctx.prisma, args.userId, bookIds),
163	      ]);
164	
165	      return orders.map((order) => {
166	        const items = order.items.map((item) => ({
167	          id: item.id,
168	          book: toBookDTO(item.book, ratings, myRatings),
169	          format: item.format,
170	          quantity: item.quantity,
171	          unitPrice: Number(item.unitPrice),
172	        }));
173	        return {
174	          id: order.id,
175	          createdAt: order.createdAt.toISOString(),
176	          items,
177	          total: orderTotal(items),
178	        };
179	      });
180	    },
181	
182	    report: async (_parent: unknown, _args: unknown, ctx: GraphQLContext) => {
183	      const [totalAgg, byGenreRows] = await Promise.all([
184	        ctx.prisma.orderItem.aggregate({ _sum: { quantity: true } }),
185	        // A purchased book counts toward every genre it belongs to, so this
186	        // has to join through BookGenre rather than a plain groupBy on
187	        // OrderItem — a book with 2 genres contributes its quantity twice.
