// TEMPORARY scratch verification for query-param syncing + default user
// selection + Report page order history. Drives the real App against the
// real running backend. Delete after use — not part of the permanent suite.
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect } from "vitest";
import { ApolloClient, HttpLink, InMemoryCache } from "@apollo/client";
import { ApolloProvider } from "@apollo/client/react";
import { MemoryRouter, useLocation } from "react-router";
import App from "@/App";
import { CurrentUserProvider } from "@/context/UserContext";
import { CartProvider } from "@/context/CartContext";

const GENRE_ID = "76f32e05-0f1c-4e6e-bb8f-2ce9160b4c88"; // Biography, from a live curl check

function LocationProbe() {
  const location = useLocation();
  return <div data-testid="location-probe">{location.pathname + location.search}</div>;
}

function renderApp(initialPath: string) {
  const client = new ApolloClient({
    link: new HttpLink({ uri: "http://localhost:4000/", fetch }),
    cache: new InMemoryCache(),
  });
  return render(
    <ApolloProvider client={client}>
      <MemoryRouter initialEntries={[initialPath]}>
        <CurrentUserProvider>
          <CartProvider>
            <LocationProbe />
            <App />
          </CartProvider>
        </CurrentUserProvider>
      </MemoryRouter>
    </ApolloProvider>,
  );
}

describe("query param sync (manual verification)", () => {
  it("hydrates Browse filters from the URL and a genre change updates it", async () => {
    const user = userEvent.setup();
    renderApp(`/?q=Harry&genre=${GENRE_ID}`);

    expect(await screen.findByDisplayValue("Harry")).toBeInTheDocument();

    // Genre select should reflect the URL-provided genre once loaded.
    await waitFor(() => expect(screen.getByText("Biography")).toBeInTheDocument());

    await user.clear(screen.getByDisplayValue("Harry"));
    await user.type(screen.getByPlaceholderText(/Search by title or author/), "Potter");

    await waitFor(
      () => expect(screen.getByTestId("location-probe").textContent).toContain("q=Potter"),
      { timeout: 3000 },
    );
    expect(screen.getByTestId("location-probe").textContent).toContain(`genre=${GENRE_ID}`);
  });

  it("auto-selects a user when none is chosen, and mirrors it into the URL", async () => {
    renderApp("/");

    await waitFor(
      () => expect(screen.getByTestId("location-probe").textContent).toMatch(/user=[\w-]+/),
      { timeout: 3000 },
    );
  });

  it("keeps the user param present after navigating to Orders", async () => {
    const user = userEvent.setup();
    renderApp("/");

    await waitFor(
      () => expect(screen.getByTestId("location-probe").textContent).toMatch(/user=[\w-]+/),
      { timeout: 3000 },
    );
    const probeBefore = screen.getByTestId("location-probe").textContent!;
    const userParam = probeBefore.match(/user=[\w-]+/)![0];

    await user.click(screen.getByRole("link", { name: "Orders" }));

    await waitFor(() => expect(screen.getByTestId("location-probe").textContent).toContain("/orders"));
    expect(screen.getByTestId("location-probe").textContent).toContain(userParam);
  });

  it("shows a paginated order history on the Report page", async () => {
    const user = userEvent.setup();
    renderApp("/report");

    expect(await screen.findByText("Order history")).toBeInTheDocument();
    await waitFor(() => expect(screen.getAllByText(/Page \d+ of \d+/).length).toBeGreaterThan(0));

    const pageLabelBefore = screen.getAllByText(/Page \d+ of \d+/)[0]!.textContent;
    await user.click(screen.getByRole("button", { name: "Next page" }));
    await waitFor(() =>
      expect(screen.getAllByText(/Page \d+ of \d+/)[0]!.textContent).not.toBe(pageLabelBefore),
    );
  });
});

