        s = json.dumps(inp)
    except Exception:
        s = str(inp)
    if len(s) > 160:
        s = s[:160] + "…"
    return s

def parse_command_block(text):
    name_m = re.search(r"<command-name>(.*?)</command-name>", text, re.S)
    args_m = re.search(r"<command-args>(.*?)</command-args>", text, re.S)
    name = name_m.group(1).strip() if name_m else None
    args = args_m.group(1).strip() if args_m else ""
    return name, args

def main():
    events = []  # list of dicts: {kind, ts, ...}

    pending_items = []  # ordered list of {"kind": "text"|"tool", "value": ...}
    pending_ts = None

    def flush_assistant():
        nonlocal pending_items, pending_ts
        if pending_items:
            events.append({
                "kind": "assistant",
                "ts": pending_ts,
                "items": list(pending_items),
            })
        pending_items = []
        pending_ts = None

    # map tool_use_id -> (tool name, question texts) for AskUserQuestion calls
    ask_user_question_ids = {}

    with open(SRC) as f:
        for raw in f:
            raw = raw.strip()
            if not raw:
                continue
            d = json.loads(raw)
            t = d.get("type")

            if t == "assistant":
                msg = d.get("message", {})
                content = msg.get("content")
                if not isinstance(content, list):
                    continue
                if pending_ts is None:
                    pending_ts = d.get("timestamp")
                for b in content:
                    bt = b.get("type")
                    if bt == "text":
                        txt = b.get("text", "").strip()
                        if txt:
                            pending_items.append({"kind": "text", "value": txt})
                    elif bt == "tool_use":
                        name = b.get("name", "?")
                        inp = b.get("input", {})
                        if name == "AskUserQuestion":
                            ask_user_question_ids[b.get("id")] = True
                        summary = summarize_tool_input(name, inp)
                        pending_items.append({
                            "kind": "tool",
                            "value": f"{name}({summary})" if summary else name,
                        })
                continue

            if t == "user":
                msg = d.get("message", {})
                content = msg.get("content")
                ts = d.get("timestamp")

                # Case 1: plain string content
                if isinstance(content, str):
                    text = content

                    if text.startswith("<local-command-stdout>"):
                        continue
                    if text.startswith("<local-command-caveat>"):
                        continue
                    if text.startswith("This session is being continued from a previous conversation"):
                        flush_assistant()
                        events.append({"kind": "compaction", "ts": ts})
                        continue
                    if text.startswith("<command-name>"):
                        flush_assistant()
                        name, args = parse_command_block(text)
                        events.append({"kind": "command", "ts": ts, "name": name, "args": args})
                        continue

                    # genuine free-typed prompt
                    flush_assistant()
                    events.append({"kind": "user", "ts": ts, "text": text.strip()})
                    continue

                # Case 2: list content
                if isinstance(content, list):
                    # tool_result(s) only?
                    text_blocks = [b for b in content if b.get("type") == "text"]
                    tool_result_blocks = [b for b in content if b.get("type") == "tool_result"]

                    if text_blocks and not tool_result_blocks:
                        joined = "\n".join(b.get("text", "") for b in text_blocks).strip()
                        flush_assistant()
                        if joined.startswith("[Request interrupted"):
                            events.append({"kind": "interrupt", "ts": ts, "text": joined})
                        else:
                            events.append({"kind": "user", "ts": ts, "text": joined})
                        continue

                    if tool_result_blocks:
                        for b in tool_result_blocks:
                            tuid = b.get("tool_use_id")
                            if tuid in ask_user_question_ids:
                                raw_content = b.get("content")
                                if isinstance(raw_content, list):
                                    raw_content = " ".join(
                                        c.get("text", "") for c in raw_content if isinstance(c, dict)
                                    )
                                m = re.findall(r'"([^"]+)"="([^"]+)"', str(raw_content))
                                if m:
                                    flush_assistant()
                                    events.append({
                                        "kind": "answered",
                                        "ts": ts,
                                        "pairs": m,
                                    })
                        continue
                continue

    flush_assistant()

    # Render
    lines = []
    lines.append("# Bookie — Full Chat Transcript\n")
    lines.append(
        "This file is a **mechanically extracted, chronological rendering** of the actual Claude Code "
        "session log for this project (not a hand-written or paraphrased summary). It was produced by a "
        "script that parses the raw session JSONL and pulls out: every prompt I typed, every slash command "
        "I invoked (with its arguments), every answer I gave to an in-conversation clarifying question, and "
        "every visible assistant response — in original order, with real timestamps.\n"
    )
    lines.append(
        "Internal assistant \"thinking\" blocks and full tool-call parameters are omitted here for "
        "readability (a single `Edit` or `Bash` call can be large); each tool call is instead shown as a "
        "one-line marker with its most relevant argument. **Nothing was edited, reworded, or summarized by "
        "an AI** — for full, byte-for-byte fidelity (including everything omitted here), see the raw, "
        "unedited `chatlog.jsonl` in this same directory, which is the actual session log file "
        "Claude Code wrote to disk in real time.\n"
    )
    lines.append("---\n")

    for ev in events:
        ts = fmt_ts(ev.get("ts"))
        kind = ev["kind"]

        if kind == "user":
            lines.append(f"### {ts} — Me\n")
            lines.append(ev["text"] + "\n")
        elif kind == "command":
            name = ev["name"]
            args = ev["args"]
            lines.append(f"### {ts} — Me (slash command)\n")
            if args:
                lines.append(f"**`{name}`** {args}\n")
            else:
                lines.append(f"**`{name}`**\n")
        elif kind == "answered":
            lines.append(f"### {ts} — Me (answered a clarifying question)\n")
            for q, a in ev["pairs"]:
                lines.append(f"- **{q}**\n  → {a}\n")
        elif kind == "interrupt":
            lines.append(f"*{ts} — {ev['text']}*\n")
        elif kind == "compaction":
            lines.append(
                f"> _{ts} — context window compacted here (Claude Code's `/compact`); an internal "
                f"summary was generated and fed back in to continue the session. That summary is not "
                f"reproduced in this document but is present verbatim in `chatlog.jsonl`._\n"
            )
        elif kind == "assistant":
            lines.append(f"### {ts} — Claude\n")
            if ev["text"]:
                lines.append(ev["text"] + "\n")
            if ev["tools"]:
                tool_lines = "\n".join(f"- 🔧 {t}" for t in ev["tools"])
                lines.append(f"<details><summary>Tool calls ({len(ev['tools'])})</summary>\n\n{tool_lines}\n\n</details>\n")

        lines.append("")

    with open(OUT, "w") as f:
        f.write("\n".join(lines))

    print("events:", len(events))
    print("wrote", OUT)

if __name__ == "__main__":
    main()

